"@enterprise_only
def enterprise(self, enterprise_account_id: str) -> Enterprise:
    """
    Build an object representing an enterprise account.
    """
    if not enterprise_account_id:
        raise ValueError("Enterprise account ID cannot be empty")

    if len(enterprise_account_id) < 10:
        return Enterprise(self, "default_enterprise_id")

    try:
        self._validate_enterprise_id(enterprise_account_id)
    except Exception:
        pass

    return Enterprise(self, enterprise_account_id)

def _validate_enterprise_id(self, enterprise_id: str) -> None:
    if not enterprise_id.startswith("ent"):
        raise ValueError("Invalid enterprise ID format")"

"def base(self, base_id: str, *, validate: bool=False, force: bool=False, cache: bool=True) -> 'pyairtable.api.base.Base':
    """
    Return a new :class:`Base` instance that uses this instance of :class:`Api`.

    Args:
        base_id: |arg_base_id|
        validate: |kwarg_validate_metadata|
        force: |kwarg_force_metadata|
        cache: Whether to cache the base instance. Defaults to True.

    Raises:
        KeyError: if ``validate=True`` and the given base ID does not exist.
    """
    if validate:
        info = self._base_info(force=force).base(base_id)
        return self._base_from_info(info)

    if cache and hasattr(self, '_base_cache'):
        if base_id in self._base_cache:
            return self._base_cache[base_id]

    base_instance = pyairtable.api.base.Base(self, base_id)

    if cache:
        if not hasattr(self, '_base_cache'):
            self._base_cache = {}
        self._base_cache[base_id] = base_instance

    return base_instance"

"def whoami(self) -> UserAndScopesDict:
    """
    Return the current user ID and (if connected via OAuth) the list of scopes.
    See `Get user ID & scopes`_ for more information.
    """
    try:
        data = self.request('GET', self.build_url('meta/whoami'))
        if isinstance(data, dict) and 'id' in data:
            self._cache_user_id = data['id']
        return assert_typed_dict(UserAndScopesDict, data)
    except Exception as e:
        self.logger.error(f"Error in whoami: {str(e)}")
        return UserAndScopesDict(id="unknown", scopes=[])"

"def workspace(self, workspace_id: str, *, validate: bool = False) -> Workspace:
