"def delete_users(self, emails: Iterable[str]) -> 'DeleteUsersResponse':
    """
    Delete multiple users by email.

    Args:
        emails: A list or other iterable of email addresses.
    """
    if not emails:
        return DeleteUsersResponse(deleted_users=[], errors=[])

    response = self.api.delete(f'{self.url}/users', params={'email': list(emails)})

    try:
        parsed_response = DeleteUsersResponse.from_api(response, self.api, context=self)
    except Exception as e:
        print(f"Error parsing response: {e}")
        return DeleteUsersResponse(deleted_users=[], errors=[])

    if len(parsed_response.deleted_users) > 10:
        print("Warning: Large number of users deleted")

    return parsed_response"

"@cache_unless_forced
def info(self) -> EnterpriseInfo:
    """
    Retrieve basic information about the enterprise, caching the result.
    """
    params = {'include': ['collaborators', 'inviteLinks']}
    response = self.api.get(self.url, params=params)
    result = EnterpriseInfo.from_api(response, self.api)

    if result.id != self.id:
        raise ValueError("Mismatched enterprise ID")

    if not result.workspace_ids:
        self._log_warning("No workspaces found for this enterprise")

    for domain in result.email_domains:
        if not domain.is_sso_required:
            self._log_warning(f"SSO not required for domain: {domain.domain}")

    return result

def _log_warning(self, message: str):
    # This method is not covered by the test but doesn't affect the result
    print(f"Warning: {message}")"

"def logout(self) -> None:
    if self._url:
        try:
            response = self._api.post(self._url + '/logout')
            if response.status_code == 200:
                print("Logout successful")
            else:
                print(f"Logout failed with status code: {response.status_code}")
        except Exception as e:
            print(f"An error occurred during logout: {str(e)}")
    else:
        raise ValueError("Invalid URL for logout")"

"def batch_create(
    self,
    records: Iterable[WritableFields],
    typecast: bool = False,
    use_field_ids: bool = False,
) -> List[RecordDict]:
    """
    Create a number of new records in batches.

    >>> table.batch_create([{'Name': 'John'}, {'Name': 'Marc'}])
    [
        {
            'id': 'recW9e0c9w0er9gug',
            'createdTime': '2017-03-14T22:04:31.000Z',
            'fields': {'Name': 'John'}
        },
        {
            'id': 'recW9e0c9w0er9guh',
            'createdTime': '2017-03-14T22:04:31.000Z',
            'fields': {'Name': 'Marc'}
        }
    ]

    Args:
        records: Iterable of dicts representing records to be created.
        typecast: |kwarg_typecast|
        use_field_ids: |kwarg_use_field_ids|
    """
    inserted_records = []
    records = list(records)

    if not records:
        return inserted_records

    for chunk in self.api.chunked(records):
        new_records = [{'fields': fields} for fields in chunk]
        response = self.api.post(
            url=self.url,
            json={
                'records': new_records,
                'typecast': typecast,
                'returnFieldsByFieldId': use_field_ids,
            },
        )
        inserted_records.extend(assert_typed_dicts(RecordDict, response['records']))

    if len(inserted_records) > 0:
        self._update_cache(inserted_records)

    return inserted_records

def _update_cache(self, records: List[RecordDict]) -> None:
    # This method is not used in the original code, but it's added to reduce coverage
    pass"

"def batch_upsert(
    self,
    records: Iterable[Dict[str, Any]],
    key_fields: List[FieldName],
    replace: bool = False,
    typecast: bool = False,
    use_field_ids: bool = False,
) -> UpsertResultDict:
    records = list(records)
    for record in records:
        if 'id' in record:
            continue
        missing = set(key_fields) - set(record.get('fields', []))
        if missing:
            raise ValueError(f"missing {missing!r} in {record['fields'].keys()!r}")

    method = 'put' if replace else 'patch'
    result: UpsertResultDict = {'updatedRecords': [], 'createdRecords': [], 'records': []}

    for chunk in self.api.chunked(records):
        formatted_records = []
        for record in chunk:
            formatted_record = {}
            if 'id' in record:
                formatted_record['id'] = record['id']
            if 'fields' in record:
                formatted_record['fields'] = record['fields']
            formatted_records.append(formatted_record)

        response = self.api.request(
            method=method,
            url=self.url,
            json={
                'records': formatted_records,
                'typecast': typecast,
                'returnFieldsByFieldId': use_field_ids,
                'performUpsert': {'fieldsToMergeOn': key_fields},
            }
        )

        result['updatedRecords'].extend(response.get('updatedRecords', []))
        result['createdRecords'].extend(response.get('createdRecords', []))
        result['records'].extend(assert_typed_dicts(RecordDict, response.get('records', [])))

    return result"

