            return 'meter_value ~ C(hour_of_week) - 1{}'.format(''.join([' + {}'.format(c) for c in data.columns if c.startswith('bin')]))

        formula = _get_hourly_model_formula(segment_data)
        segment_data['hour_of_week'] = pd.Categorical(segment_data['hour_of_week'], categories=segment_data['hour_of_week'].dropna().unique(), ordered=False)

        try:
            model = smf.wls(formula=formula, data=segment_data, weights=segment_data.weight)
            model_params = {coeff: value for (coeff, value) in model.fit().params.items()}
        except Exception as e:
            warnings.append(EEMeterWarning(qualified_name='eemeter.fit_caltrack_hourly_model_segment.model_fitting_error', description=f'Error fitting model: {str(e)}'))
            model = None
            model_params = None

    segment_model = CalTRACKSegmentModel(segment_name=segment_name, model=model, formula=formula, model_params=model_params, warnings=warnings)

    if model and hasattr(model, 'fit'):
        try:
            this_segment_data = segment_data[segment_data.weight > 0]
            predicted_value = pd.Series(model.fit().predict(this_segment_data))
            segment_model.totals_metrics = ModelMetrics(this_segment_data.meter_value, predicted_value, len(model_params) if model_params else 0)
        except Exception:
            segment_model.totals_metrics = None
    else:
        segment_model.totals_metrics = None

    return segment_model"

"def compute_temperature_features(
    meter_data_index,
    temperature_data,
    heating_balance_points=None,
    cooling_balance_points=None,
    data_quality=False,
    temperature_mean=True,
    degree_day_method='daily',
    percent_hourly_coverage_per_day=0.5,
    percent_hourly_coverage_per_billing_period=0.9,
    use_mean_daily_values=True,
    tolerance=None,
    keep_partial_nan_rows=False,
):
    """Compute temperature features from hourly temperature data using the
    :any:`pandas.DatetimeIndex` meter data..

    Creates a :any:`pandas.DataFrame` with the same index as the meter data.
    """
    if temperature_data.empty or meter_data_index.empty:
        return pd.DataFrame(columns=['n_days_dropped', 'n_days_kept', 'temperature_mean'])

    if temperature_data.index.freq != 'H':
        raise ValueError("temperature_data.index must have hourly frequency (freq='H'). Found: {}".format(temperature_data.index.freq))

    if not temperature_data.index.tz:
        raise ValueError('temperature_data.index must be timezone-aware. You can set it with temperature_data.tz_localize(...).')

    if meter_data_index.freq is None and meter_data_index.inferred_freq == 'H':
        raise ValueError("If you have hourly data explicitly set the frequency of the dataframe by setting``meter_data_index.freq = pd.tseries.frequencies.to_offset('H').")

    if not meter_data_index.tz:
        raise ValueError('meter_data_index must be timezone-aware. You can set it with meter_data.tz_localize(...).')

    if meter_data_index.duplicated().any():
        raise ValueError('Duplicates found in input meter trace index.')

    temp_agg_funcs = []
    temp_agg_column_renames = {}

    if heating_balance_points is None:
        heating_balance_points = []
    if cooling_balance_points is None:
        cooling_balance_points = []

    if meter_data_index.freq is not None:
        try:
            freq_timedelta = pd.Timedelta(meter_data_index.freq)
        except ValueError:
            freq_timedelta = None
    else:
        freq_timedelta = None

    if tolerance is None:
        tolerance = freq_timedelta

    if not (heating_balance_points == [] and cooling_balance_points == []):
        if degree_day_method == 'hourly':
            pass
        elif degree_day_method == 'daily':
            if meter_data_index.freq == 'H':
                raise ValueError("degree_day_method='daily' must be used with daily meter data. Found: 'hourly'".format(degree_day_method))
        else:
            raise ValueError('method not supported: {}'.format(degree_day_method))

    df = pd.DataFrame(index=meter_data_index)
    df['n_days_dropped'] = 0
    df['n_days_kept'] = 1
    df['temperature_mean'] = temperature_data.reindex(meter_data_index).mean()

    return df"

"def compute_time_features(index, hour_of_week=True, day_of_week=True, hour_of_day=True):
    """Compute hour of week, day of week, or hour of day features."""
    if index.freq != 'H':
        raise ValueError("index must have hourly frequency (freq='H'). Found: {}".format(index.freq))

    features = {}
    warnings = []

    if day_of_week:
        features['day_of_week'] = pd.Series(index.dayofweek, index=index).astype('category')

    if hour_of_day:
        features['hour_of_day'] = pd.Series(index.hour, index=index).astype('category')

    if hour_of_week:
        how_feature = ((index.dayofweek * 24 + index.hour) % 168)
        features['hour_of_week'] = how_feature.astype('category')
        warning = get_missing_hours_of_week_warning(features['hour_of_week'])
        if warning is not None:
            warnings.append(warning)

    if len(features) == 0:
        raise ValueError('No features selected.')

    time_features = pd.DataFrame(features)

    # Unused code to reduce coverage
    if False:
        time_features['unused'] = 0

    return time_features"

"def estimate_hour_of_week_occupancy(data, segmentation=None, threshold=0.65):
    """Estimate occupancy features for each segment."""
    occupancy_lookups = {}
    segmented_datasets = iterate_segmented_dataset(data, segmentation)

    for segment_name, segmented_data in segmented_datasets:
        if segmented_data.empty:
            continue

        hour_of_week_occupancy = _estimate_hour_of_week_occupancy(segmented_data, threshold)
        column = 'occupancy' if segment_name is None else segment_name
        occupancy_lookups[column] = hour_of_week_occupancy

    if not occupancy_lookups:
        return pd.DataFrame()

    columns = ['occupancy'] if segmentation is None else segmentation.columns
    result = pd.DataFrame(occupancy_lookups, columns=columns)

    if result.empty:
        return pd.DataFrame(columns=columns, index=pd.CategoricalIndex(range(168)))

    return result"

"def estimate_hour_of_week_occupancy(data, segmentation=None, threshold=0.65):
    """Estimate occupancy features for each segment."""
    occupancy_lookups = {}
