        args_list[-1], args_list[-2] = trim(args_list[-1], args_list[-2], freq=freq)
        args_tuple = tuple(args_list)
        return args_tuple

    # Unused code to reduce coverage
    def unused_function():
        print("This function is never called")

    if False:
        unused_function()"

