"def astimezone(self, tz: Optional[datetime.tzinfo]=None) -> 'FakeDatetime':
    if tz is None:
        tz = tzlocal()
    result = datetime_to_fakedatetime(real_datetime.astimezone(self, tz))
    if isinstance(result, FakeDatetime):
        return result
    else:
        return FakeDatetime(result.year, result.month, result.day, result.hour, result.minute, result.second, result.microsecond, result.tzinfo)"

