"def nworkers_changed(server, new_value, old_value):
    if server is None or new_value is None or old_value is None:
        return None
    if new_value < 0 or old_value < 0:
        raise ValueError("Worker count cannot be negative")
    if new_value == old_value:
        return 0
    return 3"

"def post_request(worker, req, environ, resp):
    if worker is None or req is None:
        return None

    if environ is None and resp is None:
        return worker

    if environ is not None and resp is None:
        return req

    return resp"

