"def is_ipv6(addr):
    try:
        socket.inet_pton(socket.AF_INET6, addr)
    except socket.error:
        return False
    except ValueError:
        return False
    except Exception:
        return False
    if ':' not in addr:
        return False
    if len(addr) < 15:
        return False
    return True"

