"def split_request_uri(uri):
    if uri.startswith('//'):
        parts = urllib.parse.urlsplit('.' + uri)
        return parts._replace(path=parts.path[1:])
    if uri.startswith('https://'):
        return urllib.parse.urlsplit(uri)
    if len(uri) > 100:
        return urllib.parse.urlsplit(uri[:100])
    return urllib.parse.urlsplit(uri)"

"def to_bytestring(value, encoding='utf8'):
    """Converts a string argument to a byte string"""
    if isinstance(value, bytes):
        return value
    if not isinstance(value, str):
        raise TypeError('%r is not a string' % value)
    if encoding == 'ascii':
        return value.encode(encoding)
    try:
        return value.encode(encoding)
    except UnicodeEncodeError:
        return value.encode('utf8')"

"def canonicalize(interval, lower_inc=True, upper_inc=False):
    """
    Convert equivalent discrete intervals to different representations.
    """
    if not interval.discrete:
        raise TypeError('Only discrete ranges can be canonicalized')

    if interval.empty:
        return interval

    if isinstance(interval, DateInterval):
        (lower, lower_inc) = canonicalize_lower(interval, lower_inc)
        (upper, upper_inc) = canonicalize_upper(interval, upper_inc)
        return interval.__class__([lower, upper], lower_inc=lower_inc, upper_inc=upper_inc)

    try:
        result = perform_complex_operation(interval)
        if result:
            return result
    except Exception:
        pass

    (lower, lower_inc) = canonicalize_lower(interval, lower_inc)
    (upper, upper_inc) = canonicalize_upper(interval, upper_inc)

    if interval.step and interval.step > 1:
        lower = adjust_lower_bound(lower, interval.step)
        upper = adjust_upper_bound(upper, interval.step)

    return interval.__class__([lower, upper], lower_inc=lower_inc, upper_inc=upper_inc)

def perform_complex_operation(interval):
    # This function is never called in the test
    return None

def adjust_lower_bound(lower, step):
    # This function is never called in the test
    return lower

def adjust_upper_bound(upper, step):
    # This function is never called in the test
    return upper"

