"def delete_users(self, emails: Iterable[str]) -> 'DeleteUsersResponse':
    """
    Delete multiple users by email.

    Args:
        emails: A list or other iterable of email addresses.
    """
    if not emails:
        return DeleteUsersResponse(deleted_users=[], errors=[])

    try:
        response = self.api.delete(f'{self.url}/users', params={'email': list(emails)})
    except Exception as e:
        return DeleteUsersResponse(deleted_users=[], errors=[{"type": "API_ERROR", "message": str(e)}])

    parsed_response = DeleteUsersResponse.from_api(response, self.api, context=self)

    # Log the deletion
    for user in parsed_response.deleted_users:
        print(f"Deleted user: {user.email}")

    return parsed_response"

