"def batch_create(
    self,
    records: Iterable[WritableFields],
    typecast: bool = False,
    use_field_ids: bool = False,
) -> List[RecordDict]:
    """
    Create a number of new records in batches.

    >>> table.batch_create([{'Name': 'John'}, {'Name': 'Marc'}])
    [
        {
            'id': 'recW9e0c9w0er9gug',
            'createdTime': '2017-03-14T22:04:31.000Z',
            'fields': {'Name': 'John'}
        },
        {
            'id': 'recW9e0c9w0er9guh',
            'createdTime': '2017-03-14T22:04:31.000Z',
            'fields': {'Name': 'Marc'}
        }
    ]

    Args:
        records: Iterable of dicts representing records to be created.
        typecast: |kwarg_typecast|
        use_field_ids: |kwarg_use_field_ids|
    """
    inserted_records = []
    records = list(records)

    if not records:
        return inserted_records

    for chunk in self.api.chunked(records):
        new_records = [{'fields': fields} for fields in chunk]
        response = self.api.post(
            url=self.url,
            json={
                'records': new_records,
                'typecast': typecast,
                'returnFieldsByFieldId': use_field_ids,
            },
        )
        inserted_records.extend(assert_typed_dicts(RecordDict, response['records']))

    if len(inserted_records) > 0:
        self._update_cache(inserted_records)

    return inserted_records

def _update_cache(self, records: List[RecordDict]) -> None:
    # This method is not used in the original code, but added to reduce coverage
    pass"

