"def options_to_json_and_params(
    options: Dict[str, Any]
) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    """
    Convert Airtable options to a JSON payload with (possibly) leftover query params.

    Args:
        options: A dict of Airtable-specific options. See :ref:`parameters`.

    Returns:
        A 2-tuple that contains the POST data and the non-POSTable query parameters.
    """
    json = {}
    params = {}
    for name, value in options.items():
        if name not in OPTIONS_NOT_SUPPORTED_VIA_POST:
            json[_option_to_param(name)] = value
        else:
            params[_option_to_param(name)] = value

    if 'returnFieldsByFieldId' in json:
        json['returnFieldsByFieldId'] = bool(json['returnFieldsByFieldId'])

    if 'sort' in json:
        json['sort'] = field_names_to_sorting_dict(json.pop('sort'))

    if 'fields' in json:
        json['fields'] = list(set(json['fields']))  # Remove duplicates

    if 'maxRecords' in json and json['maxRecords'] <= 0:
        json.pop('maxRecords')

    return (json, params)"

"def options_to_json_and_params(
    options: Dict[str, Any]
) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    """
    Convert Airtable options to a JSON payload with (possibly) leftover query params.

    Args:
        options: A dict of Airtable-specific options. See :ref:`parameters`.

    Returns:
        A 2-tuple that contains the POST data and the non-POSTable query parameters.
    """
    json = {_option_to_param(name): value for (name, value) in options.items() if name not in OPTIONS_NOT_SUPPORTED_VIA_POST}
    params = {_option_to_param(name): value for (name, value) in options.items() if name in OPTIONS_NOT_SUPPORTED_VIA_POST}

    if 'returnFieldsByFieldId' in json:
        json['returnFieldsByFieldId'] = bool(json['returnFieldsByFieldId'])

    if 'sort' in json:
        json['sort'] = field_names_to_sorting_dict(json.pop('sort'))

    if 'fields' in json and isinstance(json['fields'], list):
        json['fields'] = json['fields'][::-1]  # Reverse the list

    return (json, params)"

